const ALLOWED_ORIGIN="https://cderses.github.io",T=9000,C=20000,MIN=5000;let cache={at:0,body:null};function iso(d){return d.slice(0,4)+"-"+d.slice(4,6)+"-"+d.slice(6,8)}function parse(t){const out=[],re=/BEGIN:VEVENT([\s\S]*?)END:VEVENT/g,u=String(t).replace(/\r?\n[ \t]/g,"");let x;while((x=re.exec(u))){const b=x[1],s=/DTSTART[^:\r\n]*:(\d{8})/.exec(b),e=/DTEND[^:\r\n]*:(\d{8})/.exec(b);if(s&&e)out.push([iso(s[1]),iso(e[1])])}return out}async function get(u){const c=new AbortController(),h=setTimeout(()=>c.abort(),T);try{const r=await fetch(u,{signal:c.signal});if(!r.ok)throw new Error("HTTP "+r.status);return r.text()}finally{clearTimeout(h)}}function icalMap(env){let raw=((env&&env.ICAL_MAP_JSON)||"").trim();if(!raw)throw new Error("ICAL_MAP_JSON secret is not set");if(raw[0]!=="{")raw=atob(raw);const map=JSON.parse(raw);if(!map||typeof map!=="object"||Array.isArray(map))throw new Error("ICAL_MAP_JSON must be an object of listing_id -> ical_url");return map}async function build(env){const map=icalMap(env),ids=Object.keys(map),rooms={},errors=[];const res=await Promise.all(ids.map(id=>get(map[id]).then(t=>[id,parse(t)]).catch(e=>{errors.push({listing_id:id,error:String(e)});return[id,[]]})));res.forEach(p=>{rooms[p[0]]={blocked:p[1]}});return{updated_at:new Date(Date.now()+324e5).toISOString().slice(0,19)+"+09:00",rooms,errors}}export default{async fetch(request,env){const h={"content-type":"application/json","access-control-allow-origin":ALLOWED_ORIGIN,vary:"origin"};try{const fresh=new URL(request.url).searchParams.get("fresh")==="1",stale=!cache.body||Date.now()-cache.at>C,cooled=cache.body&&Date.now()-cache.at<MIN;if(stale&&!(fresh&&cooled)){const body=await build(env);cache={at:Date.now(),body}}return new Response(JSON.stringify(cache.body),{headers:h})}catch(e){return new Response(JSON.stringify({error:"upstream_failed",detail:String(e)}),{status:502,headers:h})}}};
